/**
 * 📡 RÈGLE ABSOLUE « l'appli s'ouvre toujours, même sans réseau » (2026-11-02, copie de l'Agenda).
 * Sans réseau, le renouvellement du jeton de connexion échoue et Supabase réessaie pendant ~25 s en bloquant
 * toute l'appli, puis renvoie vers la connexion. Ici, le renouvellement est limité à 8 s ; s'il échoue faute de
 * réseau (mode avion, wifi sans Internet), on répond avec la session déjà enregistrée sur l'appareil, valable
 * 3 minutes (au-delà des 90 s où Supabase juge un jeton « bientôt expiré », sinon boucle de renouvellement) : l'appli s'ouvre tout de suite avec les dernières données en mémoire, et le vrai renouvellement est
 * retenté jusqu'au retour du réseau. Une vraie réponse du serveur (jeton refusé…) passe toujours telle quelle.
 */
export const AUTH_STORAGE_KEY = `sb-${new URL(SUPABASE_URL).hostname.split('.')[0]}-auth-token`;
const REFRESH_TIMEOUT_MS = 8000;

/**
 * 🔁 Session de secours (2026-11-09, accueil vide de Nadia au réveil du Mac : jeton expiré depuis 5 h,
 * 1er renouvellement raté → l'appli a gardé l'ancien jeton et la base refusait tout) :
 *  - tant que la session de secours est utilisée, on retente le VRAI renouvellement toutes les 10 s ;
 *  - dès qu'il réussit, l'événement `dinislam:session-renouvelee` fait recharger toutes les données
 *    et le statut (admin, compte validé) — sans que l'utilisateur ait à recharger la page.
 */
export const SESSION_RENOUVELEE_EVENT = 'dinislam:session-renouvelee';
let sessionDeSecours = false;
let relance: ReturnType<typeof setTimeout> | null = null;
function marquerSecours() {
  sessionDeSecours = true;
  if (relance) return;
  relance = setTimeout(() => {
    relance = null;
    void supabase.auth.refreshSession().catch(() => {});
  }, 10000);
}
function marquerRenouvelee() {
  if (!sessionDeSecours) return;
  sessionDeSecours = false;
  if (relance) { clearTimeout(relance); relance = null; }
  // Laisse Supabase enregistrer le nouveau jeton avant de relancer les requêtes
  setTimeout(() => { try { window.dispatchEvent(new Event(SESSION_RENOUVELEE_EVENT)); } catch { /* rien */ } }, 300);
}

function offlineRefreshResponse(): Response | null {
  try {
    const raw = localStorage.getItem(AUTH_STORAGE_KEY);
    const stored = raw ? JSON.parse(raw) : null;
    const s = stored?.currentSession ?? stored;
    if (!s?.access_token || !s?.refresh_token || !s?.user) return null;
    const body = { access_token: s.access_token, refresh_token: s.refresh_token, token_type: 'bearer', expires_in: 180, expires_at: Math.floor(Date.now() / 1000) + 180, user: s.user };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'Content-Type': 'application/json' } });
  } catch {
    return null;
  }
}

const resilientFetch: typeof fetch = async (input, init) => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
  if (!url.includes('/auth/v1/token') || !url.includes('grant_type=refresh_token')) return fetch(input, init);
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    const offline = offlineRefreshResponse();
    if (offline) { marquerSecours(); return offline; }
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REFRESH_TIMEOUT_MS);
  try {
    const response = await fetch(input, { ...init, signal: controller.signal });
    if (response.ok) marquerRenouvelee();
    return response;
  } catch (err) {
    const offline = offlineRefreshResponse();
    if (offline) { marquerSecours(); return offline; }
    throw err;
  } finally {
    clearTimeout(timer);
  }
};

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: { fetch: resilientFetch },
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  }
});

/**
 * 🔌 Canaux « en direct » : un nom UNIQUE à chaque ouverture (2026-11-09).
 * Depuis supabase-js 2.119, ouvrir deux fois un canal du même nom (ex. le badge des messages, affiché dans
 * l'en-tête ET le menu du bas) plante l'écran : « cannot add postgres_changes callbacks … after subscribe() ».
 * L'appli n'utilise que des abonnements aux changements de tables (ni « présence » ni « diffusion »),
 * donc le nom du canal ne sert à rien d'autre : un suffixe unique est sans risque et protège aussi les futurs canaux.
 */
const canalOriginal = supabase.channel.bind(supabase);
let numeroCanal = 0;
supabase.channel = ((nom: string, ...reste: unknown[]) =>
  (canalOriginal as (n: string, ...r: unknown[]) => ReturnType<typeof canalOriginal>)(`${nom}-${++numeroCanal}-${Math.random().toString(36).slice(2, 8)}`, ...reste)
) as typeof supabase.channel;
